import sys

def from_base(x, want, units):
    return round(x / units[want], 2)

_UNITS = {"h": 3600000, "ms": 1, "s": 1000}

def _convert(data, units=None):
    units = units or _UNITS
    readings = data.get("readings", data.get("Readings", []))
    want = data.get("want", data.get("Want"))
    values = []
