{"files": {"src/producer.py": "import sys
import json

UNITS = {"h": 3600000, "ms": 1, "s": 1000}

def to_base(v, u, units):
    return v * units[u]

def main():
    req = sys.argv[1] if len(sys.argv) > 1 else None
    resp = sys.argv[2] if len(sys.argv) > 2 else None
    with open(req, 'r') as f:
        obj = json.load(f)
    readings = obj.get('readings', obj.get('Readings', []))
    want = obj.get('want', obj.get('Want'))
    units = obj.get('units', obj.get('Units', UNITS))
    # ensure units includes defaults
    for k, val in UNITS.items():
        if k not in units:
            units[k] = val
    want_size = units[want]
    values = []
    for r in readings:
        if isinstance(r, dict):
            v = r.get('v', r.get('V', r.get('value', r.get('Value'))))
            u = r.get('u', r.get('U', r.get('unit', r.get('Unit'))))
        else:
            v, u = r
        base = to_base(v, u, units)
        out = round(base / want_size, 2)
        values.append(float(out))
    out_obj = {"values": values}
    with open(resp, 'w') as f:
        json.dump(out_obj, f)

if __name__ == '__main__':
    main()
"}, "notes": "Fixed to_base to multiply by unit size and added CLI that converts via base unit then divides by wanted size rounded to 2 decimals."}
